514	        Stdout: AsyncRead + Unpin + Send + 'static,
515	        Stderr: AsyncRead + Unpin + Send + 'static,
516	        F: Fn(&NotificationOrRequest) -> bool + 'static + Send + Sync + Clone,
517	    {
518	        let (outbound_tx, outbound_rx) = async_channel::unbounded::<String>();
519	        let (output_done_tx, output_done_rx) = barrier::channel();
520	        let notification_handlers =
521	            Arc::new(Mutex::new(HashMap::<_, NotificationHandler>::default()));
522	        let response_handlers =
523	            Arc::new(Mutex::new(Some(HashMap::<_, ResponseHandler>::default())));
524	        let pending_respond_tasks = PendingRespondTasks::default();
525	        let io_handlers = Arc::new(Mutex::new(HashMap::default()));
526	
527	        let stdout_input_task = cx.spawn({
528	            let unhandled_notification_wrapper = {
529	                let response_channel = outbound_tx.clone();
530	                async move |msg: NotificationOrRequest| {
531	                    let did_handle = on_unhandled_notification(&msg);
532	                    if !did_handle && let Some(message_id) = msg.id {
533	                        let response = AnyResponse {
534	                            jsonrpc: JSON_RPC_VERSION,
535	                            id: message_id,
536	                            error: Some(Error {
537	                                code: -32601,
538	                                message: format!("Unrecognized method `{}`", msg.method),
539	                                data: None,
540	                            }),
541	                            result: None,
542	                        };
543	                        if let Ok(response) = serde_json::to_string(&response) {
544	                            response_channel.send(response).await.ok();
545	                        }
546	                    }
547	                }
548	            };
549	            let notification_handlers = notification_handlers.clone();
550	            let response_handlers = response_handlers.clone();
551	            let io_handlers = io_handlers.clone();
552	            let pending_respond_tasks = pending_respond_tasks.clone();
553	            async move |cx| {
554	                Self::handle_incoming_messages(
555	                    stdout,
556	                    unhandled_notification_wrapper,
557	                    notification_handlers,
558	                    response_handlers,
559	                    pending_respond_tasks,
560	                    io_handlers,
561	                    cx,
562	                )
563	                .log_err()
564	                .await
565	            }
566	        });
567	        let stderr_input_task = stderr
568	            .map(|stderr| {
569	                let io_handlers = io_handlers.clone();
570	                let stderr_captures = stderr_capture.clone();
571	                cx.background_spawn(async move {
572	                    Self::handle_stderr(stderr, io_handlers, stderr_captures)
573	                        .log_err()
574	                        .await
575	                })
576	            })
577	            .unwrap_or_else(|| Task::ready(None));
578	        let input_task = cx.background_spawn(async move {
579	            let (stdout, stderr) = futures::join!(stdout_input_task, stderr_input_task);
580	            stdout.or(stderr)
581	        });
582	        let output_task = cx.background_spawn({
583	            Self::handle_outgoing_messages(
584	                stdin,
585	                outbound_rx,
586	                output_done_tx,
587	                response_handlers.clone(),
588	                io_handlers.clone(),
589	            )
590	            .log_err()
591	        });
592	
593	        let configuration = DidChangeConfigurationParams {
594	            settings: Value::Null,
595	        }
596	        .into();
597	
598	        let (notification_tx, notification_rx) =
599	            async_channel::unbounded::<NotificationSerializer>();
600	        cx.background_spawn({
601	            let outbound_tx = outbound_tx.clone();
602	            async move {
603	                while let Ok(serializer) = notification_rx.recv().await {
604	                    let serialized = (serializer.0)();
605	                    let Ok(_) = outbound_tx.send(serialized).await else {
606	                        return;
607	                    };
608	                }
609	                outbound_tx.close();
610	            }
611	        })
612	        .detach();
613	        Self {
614	            server_id,
615	            notification_handlers,
616	            notification_tx,
617	            response_handlers,
618	            pending_respond_tasks,
619	            io_handlers,
620	            name: server_name,
621	            version: None,
622	            process_name: binary
623	                .path
624	                .file_name()
625	                .map(|name| Arc::from(name.to_string_lossy()))
626	                .unwrap_or_default(),
627	            binary,
628	            capabilities: Default::default(),
629	            configuration,
630	            code_action_kinds,
631	            next_id: Default::default(),
632	            outbound_tx,
633	            executor: cx.background_executor().clone(),
634	            io_tasks: Mutex::new(Some((input_task, output_task))),
635	            output_done_rx: Mutex::new(Some(output_done_rx)),
636	            server: Arc::new(Mutex::new(server)),
637	            workspace_folders,
638	            root_uri,
639	        }
640	    }
