647	    async fn handle_incoming_messages<Stdout>(
648	        stdout: Stdout,
649	        on_unhandled_notification: impl AsyncFn(NotificationOrRequest) + 'static + Send,
650	        notification_handlers: Arc<Mutex<HashMap<&'static str, NotificationHandler>>>,
651	        response_handlers: Arc<Mutex<Option<HashMap<RequestId, ResponseHandler>>>>,
652	        pending_respond_tasks: PendingRespondTasks,
653	        io_handlers: Arc<Mutex<HashMap<i32, IoHandler>>>,
654	        cx: &mut AsyncApp,
655	    ) -> anyhow::Result<()>
656	    where
657	        Stdout: AsyncRead + Unpin + Send + 'static,
658	    {
659	        let stdout = BufReader::new(stdout);
660	        let _clear_response_handlers = gpui_util::defer({
661	            let response_handlers = response_handlers.clone();
662	            move || {
663	                response_handlers.lock().take();
664	            }
665	        });
666	        let mut input_handler = input_handler::LspStdoutHandler::new(
667	            stdout,
668	            response_handlers,
669	            io_handlers,
670	            cx.background_executor().clone(),
671	        );
672	
673	        while let Some(msg) = input_handler.incoming_messages.next().await {
674	            if msg.method == <notification::Cancel as notification::Notification>::METHOD {
675	                if let Some(params) = msg.params {
676	                    if let Ok(cancel_params) = serde_json::from_value::<CancelParams>(params) {
677	                        let id = match cancel_params.id {
678	                            NumberOrString::Number(id) => RequestId::Int(id),
679	                            NumberOrString::String(id) => RequestId::Str(id),
680	                        };
681	                        pending_respond_tasks.lock().remove(&id);
682	                    }
683	                }
684	                continue;
685	            }
686	
687	            let unhandled_message = {
688	                let mut notification_handlers = notification_handlers.lock();
689	                if let Some(handler) = notification_handlers.get_mut(msg.method.as_str()) {
690	                    handler(msg.id, msg.params.unwrap_or(Value::Null), cx);
691	                    None
692	                } else {
693	                    Some(msg)
694	                }
695	            };
696	
697	            if let Some(msg) = unhandled_message {
698	                on_unhandled_notification(msg).await;
699	            }
700	
701	            // Don't starve the main thread when receiving lots of notifications at once.
702	            futures_lite::future::yield_now().await;
703	        }
704	        input_handler.loop_handle.await
705	    }
