707	    async fn handle_stderr<Stderr>(
708	        stderr: Stderr,
709	        io_handlers: Arc<Mutex<HashMap<i32, IoHandler>>>,
710	        stderr_capture: Arc<Mutex<Option<String>>>,
711	    ) -> anyhow::Result<()>
712	    where
713	        Stderr: AsyncRead + Unpin + Send + 'static,
714	    {
715	        let mut stderr = BufReader::new(stderr);
716	        let mut buffer = Vec::new();
717	
718	        loop {
719	            buffer.clear();
720	
721	            let bytes_read = stderr.read_until(b'\n', &mut buffer).await?;
722	            if bytes_read == 0 {
723	                return Ok(());
724	            }
725	
726	            if let Ok(message) = std::str::from_utf8(&buffer) {
727	                log::trace!("incoming stderr message:{message}");
728	                for handler in io_handlers.lock().values_mut() {
729	                    handler(IoKind::StdErr, message);
730	                }
731	
732	                if let Some(stderr) = stderr_capture.lock().as_mut() {
733	                    stderr.push_str(message);
734	                }
735	            }
736	
737	            // Don't starve the main thread when receiving lots of messages at once.
738	            futures_lite::future::yield_now().await;
739	        }
740	    }
741	
742	    async fn handle_outgoing_messages<Stdin>(
743	        stdin: Stdin,
744	        outbound_rx: async_channel::Receiver<String>,
745	        output_done_tx: barrier::Sender,
746	        response_handlers: Arc<Mutex<Option<HashMap<RequestId, ResponseHandler>>>>,
747	        io_handlers: Arc<Mutex<HashMap<i32, IoHandler>>>,
748	    ) -> anyhow::Result<()>
749	    where
750	        Stdin: AsyncWrite + Unpin + Send + 'static,
751	    {
752	        let mut stdin = BufWriter::new(stdin);
753	        let _clear_response_handlers = util::defer({
754	            let response_handlers = response_handlers.clone();
755	            move || {
756	                response_handlers.lock().take();
757	            }
758	        });
759	        let mut content_len_buffer = Vec::new();
760	        while let Ok(message) = outbound_rx.recv().await {
761	            log::trace!("outgoing message:{}", message);
762	            for handler in io_handlers.lock().values_mut() {
763	                handler(IoKind::StdIn, &message);
764	            }
765	
766	            content_len_buffer.clear();
767	            write!(content_len_buffer, "{}", message.len()).unwrap();
768	            stdin.write_all(CONTENT_LEN_HEADER.as_bytes()).await?;
769	            stdin.write_all(&content_len_buffer).await?;
770	            stdin.write_all("\r\n\r\n".as_bytes()).await?;
771	            stdin.write_all(message.as_bytes()).await?;
772	            stdin.flush().await?;
773	        }
774	        drop(output_done_tx);
775	        Ok(())
776	    }
