1110	    /// Sends a shutdown request to the language server process and prepares the [`LanguageServer`] to be dropped.
1111	    pub fn shutdown(&self) -> Option<impl 'static + Send + Future<Output = Option<()>> + use<>> {
1112	        let tasks = self.io_tasks.lock().take()?;
1113	
1114	        let response_handlers = self.response_handlers.clone();
1115	        let next_id = AtomicI32::new(self.next_id.load(SeqCst));
1116	        let outbound_tx = self.outbound_tx.clone();
1117	        let executor = self.executor.clone();
1118	        let notification_serializers = self.notification_tx.clone();
1119	        let mut output_done = self.output_done_rx.lock().take().unwrap();
1120	        let shutdown_request = Self::request_internal::<request::Shutdown>(
1121	            &next_id,
1122	            &response_handlers,
1123	            &outbound_tx,
1124	            &notification_serializers,
1125	            &executor,
1126	            SERVER_SHUTDOWN_TIMEOUT,
1127	            (),
1128	        );
1129	
1130	        let server = self.server.clone();
1131	        let name = self.name.clone();
1132	        let server_id = self.server_id;
1133	        let mut timer = self.executor.timer(SERVER_SHUTDOWN_TIMEOUT).fuse();
1134	        Some(async move {
1135	            log::debug!("language server shutdown started");
1136	
1137	            select! {
1138	                request_result = shutdown_request.fuse() => {
1139	                    match request_result {
1140	                        ConnectionResult::Timeout => {
1141	                            log::warn!("timeout waiting for language server {name} (id {server_id}) to shutdown");
1142	                        },
1143	                        ConnectionResult::ConnectionReset => {
1144	                            log::warn!("language server {name} (id {server_id}) closed the shutdown request connection");
1145	                        },
1146	                        ConnectionResult::Result(Err(e)) => {
1147	                            log::error!("Shutdown request failure, server {name} (id {server_id}): {e:#}");
1148	                        },
1149	                        ConnectionResult::Result(Ok(())) => {}
1150	                    }
1151	                }
1152	
1153	                _ = timer => {
1154	                    log::info!("timeout waiting for language server {name} (id {server_id}) to shutdown");
1155	                },
1156	            }
1157	
1158	            response_handlers.lock().take();
1159	            Self::notify_internal::<notification::Exit>(&notification_serializers, ()).ok();
1160	            notification_serializers.close();
1161	            output_done.recv().await;
1162	            server.lock().take().map(|mut child| child.kill());
1163	            drop(tasks);
1164	            log::debug!("language server shutdown finished");
1165	            Some(())
1166	        })
1167	    }
