1249	    fn on_custom_request<Params, Res, Fut, F>(&self, method: &'static str, mut f: F) -> Subscription
1250	    where
1251	        F: 'static + FnMut(Params, &mut AsyncApp) -> Fut + Send,
1252	        Fut: 'static + Future<Output = Result<Res>>,
1253	        Params: DeserializeOwned + Send + 'static,
