1967	        timeout: Duration,
1968	    ) -> ConnectionResult<T::Result>
1969	    where
1970	        T: request::Request,
1971	        T::Result: 'static + Send,
1972	    {
1973	        self.server.request::<T>(params, timeout).await
1974	    }
1975	
1976	    /// Attempts [`Self::try_receive_notification`], unwrapping if it has not received the specified type yet.
1977	    pub async fn receive_notification<T: notification::Notification>(&mut self) -> T::Params {
1978	        self.try_receive_notification::<T>().await.unwrap()
1979	    }
1980	
1981	    /// Consumes the notification channel until it finds a notification for the specified type.
1982	    pub async fn try_receive_notification<T: notification::Notification>(
1983	        &mut self,
1984	    ) -> Option<T::Params> {
1985	        loop {
1986	            let (method, params) = self.notifications_rx.recv().await.ok()?;
1987	            if method == T::METHOD {
1988	                return Some(serde_json::from_str::<T::Params>(&params).unwrap());
1989	            } else {
1990	                log::info!("skipping message in fake language server {:?}", params);
1991	            }
1992	        }
1993	    }
1994	
1995	    /// Registers a handler for a specific kind of request. Removes any existing handler for specified request type.
1996	    pub fn set_request_handler<T, F, Fut>(
1997	        &self,
1998	        mut handler: F,
1999	    ) -> futures::channel::mpsc::UnboundedReceiver<()>
2000	    where
2001	        T: 'static + request::Request,
2002	        T::Params: 'static + Send,
2003	        F: 'static + Send + FnMut(T::Params, gpui::AsyncApp) -> Fut,
2004	        Fut: 'static + Future<Output = Result<T::Result>>,
2005	    {
2006	        let (responded_tx, responded_rx) = futures::channel::mpsc::unbounded();
2007	        self.server.remove_request_handler::<T>();
2008	        self.server
2009	            .on_request::<T, _, _>(move |params, cx| {
2010	                let result = handler(params, cx.clone());
2011	                let responded_tx = responded_tx.clone();
2012	                let executor = cx.background_executor().clone();
2013	                async move {
2014	                    let _guard = gpui_util::defer({
2015	                        let responded_tx = responded_tx.clone();
2016	                        move || {
2017	                            responded_tx.unbounded_send(()).ok();
2018	                        }
2019	                    });
2020	                    executor.simulate_random_delay().await;
2021	                    result.await
2022	                }
2023	            })
2024	            .detach();
2025	        responded_rx
2026	    }
2027	
2028	    /// Registers a handler for a specific kind of notification. Removes any existing handler for specified notification type.
2029	    pub fn handle_notification<T, F>(
2030	        &self,
2031	        mut handler: F,
2032	    ) -> futures::channel::mpsc::UnboundedReceiver<()>
2033	    where
2034	        T: 'static + notification::Notification,
2035	        T::Params: 'static + Send,
2036	        F: 'static + Send + FnMut(T::Params, gpui::AsyncApp),
2037	    {
2038	        let (handled_tx, handled_rx) = futures::channel::mpsc::unbounded();
2039	        self.server.remove_notification_handler::<T>();
2040	        self.server
2041	            .on_notification::<T, _>(move |params, cx| {
2042	                handler(params, cx.clone());
2043	                handled_tx.unbounded_send(()).ok();
2044	            })
2045	            .detach();
2046	        handled_rx
2047	    }
2048	
2049	    /// Removes any existing handler for specified notification type.
2050	    pub fn remove_request_handler<T>(&mut self)
2051	    where
2052	        T: 'static + request::Request,
2053	    {
2054	        self.server.remove_request_handler::<T>();
2055	    }
